using System;

namespace DrivingSim.Core
{
    // Data model of Resources/Layouts/TestTownLayout.json (generated by Tools/asset-spec/generate_test_town_layout.py).
    // The JSON is the single source of truth for the test town: gameplay, the greybox builder and Codex's Blender
    // scenes all read it. Unity world coordinates: meters, Y up, +Z north, +X east. Polygons are [x0, z0, x1, z1, ...].

    [Serializable] public class TownRoad { public string id; public string axis; public float center; public float from; public float to;
        public int lanesPositive; public int lanesNegative; public float laneWidth; public float width; public string centerLine; public float[] points; }
    [Serializable] public class TownCorner { public string id; public float[] center; public float radius; public string quadrant; }
    [Serializable] public class TownIntersection { public string id; public string type; public float[] center; public float[] points; }
    [Serializable] public class TownCrosswalk { public string id; public string intersection; public string stripeAxis; public float stripeWidth; public float stripeGap; public float[] points; }
    [Serializable] public class TownStopLine { public string id; public string intersection; public string approach; public float width; public float[] points; }
    [Serializable] public class TownLaneMarking { public string id; public string type; public string axis; public float offset; public float from; public float to;
        public float width; public float dash; public float gap; }
    [Serializable] public class TownSignal { public string id; public string intersection; public string approach; public string type;
        public float[] pole; public float[] head; public float yawDeg; public float armLength; public string[] lamps; }
    [Serializable] public class TownSignalPhase { public string phase; public float durationS; public string main; public string cross; }
    [Serializable] public class TownZone { public string id; public string kind; public float maxHeight; public string note; public float[] points; }
    [Serializable] public class TownSpawn { public string id; public float[] position; public float yawDeg; public string note; }
    [Serializable] public class TownFurnitureBand { public float fromCurbFace; public float toCurbFace; public string note; }

    [Serializable]
    public class TownLayoutData
    {
        public int version;
        public string name;
        public float roadSurfaceY, curbHeight, curbWidth, sidewalkWidth, blockGroundY, worldHalfSize;
        public TownRoad[] roads;
        public TownCorner[] corners;
        public TownIntersection[] intersections;
        public TownCrosswalk[] crosswalks;
        public TownStopLine[] stopLines;
        public TownLaneMarking[] laneMarkings;
        public TownSignal[] signals;
        public TownSignalPhase[] signalCycle;
        public TownZone[] keepOut;
        public TownZone[] decorationZones;
        public TownSpawn[] spawns;
        public TownFurnitureBand furnitureBand;

        public const string ResourcePath = "Layouts/TestTownLayout";
    }

    // Street dressing (Resources/Layouts/TestTownDressing.json, generated by Tools/asset-spec/generate_test_town_dressing.py).
    [Serializable] public class TownSign { public string id; public string type; public string value; public string[] lines;
        public float[] position; public float yawDeg; public float faceHeight; public float[] size; public string prefab; }
    [Serializable] public class TownProp { public string id; public string kind; public float[] position; public float yawDeg; public string prefab; public bool onRoad; }

    [Serializable]
    public class TownDressingData
    {
        public int version;
        public int layoutVersion;
        public TownSign[] signs;
        public TownProp[] props;

        public const string ResourcePath = "Layouts/TestTownDressing";
    }

    public static class TownGeometry
    {
        /// <summary>Axis-aligned bounds of a flat [x, z, ...] polygon: (minX, minZ, maxX, maxZ).</summary>
        public static (float minX, float minZ, float maxX, float maxZ) Bounds(float[] points)
        {
            float minX = float.MaxValue, minZ = float.MaxValue, maxX = float.MinValue, maxZ = float.MinValue;
            for (int i = 0; i + 1 < points.Length; i += 2)
            {
                if (points[i] < minX) minX = points[i];
                if (points[i] > maxX) maxX = points[i];
                if (points[i + 1] < minZ) minZ = points[i + 1];
                if (points[i + 1] > maxZ) maxZ = points[i + 1];
            }
            return (minX, minZ, maxX, maxZ);
        }

        /// <summary>Point-in-polygon (even-odd) for flat [x, z, ...] outlines; works for triangles and concave shapes.</summary>
        public static bool Inside(float[] poly, float x, float z)
        {
            bool inside = false;
            int n = poly.Length / 2;
            for (int i = 0, j = n - 1; i < n; j = i++)
            {
                float xi = poly[i * 2], zi = poly[i * 2 + 1], xj = poly[j * 2], zj = poly[j * 2 + 1];
                if ((zi > z) != (zj > z) && x < (xj - xi) * (z - zi) / (zj - zi + 1e-9f) + xi) inside = !inside;
            }
            return inside;
        }

        public static bool Contains(float[] points, float x, float z, float tolerance = 1e-3f)
        {
            var b = Bounds(points);
            return x >= b.minX - tolerance && x <= b.maxX + tolerance && z >= b.minZ - tolerance && z <= b.maxZ + tolerance;
        }
    }
}
